netlify/functions/admin-action.js
//
// Called by admin.html when the admin clicks Received / Confirmed /
// Rejected / Waitlist for a registrant. Sends the matching email through
// Gmail (using an App Password, not your real Gmail password) and records
// the new status in Netlify Blobs so admin-list.js reflects it next time.

const { getStore } = require("@netlify/blobs");
const nodemailer = require("nodemailer");

const INVITE_POSTER_B64 = "";
const INVITE_PROGRAM_B64 = "";

const ORG_NAME = "Sangguniang Kabataan ng Alapan II-A";

function template(action, name, referenceNumber) {
  const safeName = name && name.trim() ? name.trim() : "there";
  const refLine = referenceNumber ? ("\nReference No: " + referenceNumber + "\n") : "\n";

  if (action === "received") {
    return {
      subject: "Gawad Parangal \u2014 We've Received Your Registration",
      text:
`Hi ${safeName},
${refLine}
We've received your registration and personal information for Gawad Parangal.

Data Privacy Notice: the details and documents you submitted (including your address, contact information, and uploaded ID) are collected solely to verify your eligibility for this event, and will only be used for that purpose by ${ORG_NAME}.

You will receive the result of your registration \u2014 including your invitation, if confirmed \u2014 within 24 hours.

Thank you,
${ORG_NAME}`
    };
  }

  if (action === "confirmed") {
    return {
      subject: "Gawad Parangal \u2014 You're Invited!",
      text:
`Hi ${safeName},
${refLine}
Congratulations! Your registration has been verified, and you are officially invited to Gawad Parangal.

Please find your official invitation and the event program flow attached.

We look forward to celebrating with you.

${ORG_NAME}`,
      attachments: [
        { filename: "Gawad-Parangal-Invitation.jpg", content: INVITE_POSTER_B64, encoding: "base64" },
        { filename: "Gawad-Parangal-Program-Flow.jpg", content: INVITE_PROGRAM_B64, encoding: "base64" }
      ]
    };
  }

  if (action === "rejected") {
    return {
      subject: "Gawad Parangal \u2014 Registration Update",
      text:
`Hi ${safeName},
${refLine}
Thank you for registering for Gawad Parangal. After reviewing your submission, we were unable to confirm your invitation at this time.

This may be due to one or more of the following:
- Your address could not be verified as being within Alapan II-A
- Your award date falls outside the recognized coverage period (September 2025 \u2013 August 2026)
- Submitted documents were incomplete, unclear, or could not be verified

If you believe this was a mistake, please reach out to us directly so we can take another look.

${ORG_NAME}`
    };
  }

  if (action === "waitlist") {
    return {
      subject: "Gawad Parangal \u2014 Waitlist Notice",
      text:
`Hi ${safeName},
${refLine}
Thank you for registering for Gawad Parangal. Our first 50 slots have already been filled.

You have been placed on the waitlist. If a slot opens up, we will reach out to you directly.

Thank you for your understanding.

${ORG_NAME}`
    };
  }

  return null;
}

exports.handler = async function (event) {
  const passcode = event.headers["x-admin-passcode"];
  if (!passcode || passcode !== process.env.ADMIN_PASSCODE) {
    return { statusCode: 401, body: JSON.stringify({ error: "Unauthorized" }) };
  }
  if (event.httpMethod !== "POST") {
    return { statusCode: 405, body: JSON.stringify({ error: "Method not allowed" }) };
  }

  let payload;
  try {
    payload = JSON.parse(event.body || "{}");
  } catch (e) {
    return { statusCode: 400, body: JSON.stringify({ error: "Invalid JSON body" }) };
  }

  const { submissionId, action, name, email } = payload;
  if (!submissionId || !action || !email) {
    return { statusCode: 400, body: JSON.stringify({ error: "submissionId, action, and email are required" }) };
  }

  let referenceNumber = null;
  try {
    const refStore = getStore("registrant-refs");
    const refData = await refStore.get(submissionId, { type: "json" });
    if (refData && refData.referenceNumber) referenceNumber = refData.referenceNumber;
  } catch (e) {
    // reference number not assigned yet — email still sends, just without it
  }

  const content = template(action, name, referenceNumber);
  if (!content) {
    return { statusCode: 400, body: JSON.stringify({ error: "Unknown action: " + action }) };
  }

  if (!process.env.GMAIL_USER || !process.env.GMAIL_APP_PASSWORD) {
    return {
      statusCode: 500,
      body: JSON.stringify({ error: "Missing GMAIL_USER or GMAIL_APP_PASSWORD environment variable." })
    };
  }

  try {
    const transporter = nodemailer.createTransport({
      service: "gmail",
      auth: {
        user: process.env.GMAIL_USER,
        pass: process.env.GMAIL_APP_PASSWORD
      }
    });

    await transporter.sendMail({
      from: `${ORG_NAME} <${process.env.GMAIL_USER}>`,
      to: email,
      subject: content.subject,
      text: content.text,
      attachments: content.attachments || []
    });

    const store = getStore("registrant-status");
    await store.setJSON(submissionId, { status: action, updatedAt: new Date().toISOString() });

    return { statusCode: 200, headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ok: true }) };
  } catch (err) {
    return { statusCode: 500, body: JSON.stringify({ error: String(err && err.message || err) }) };
  }
};
